const DrawingTool = () => {
    const [vertices, setVertices] = useState([]);

    const onPointerDown = (event) => {
        if (!vertices.length || !vertices[vertices.length - 1]) {
            // Create a new vertex at the current pointer position
            const newVertex = {
                x: event.clientX,
                y: event.clientY,
            };
            setVertices([...vertices, newVertex]);
