func createGravitationalLensShader(device: MTLDevice) -> MTLFunction {
    guard let library = device.makeDefaultLibrary() else {
        fatalError("Failed to create default library")
    }

    let gravityConstantBuffer = device.makeBuffer(length: MemoryLayout<MTLVertexDescriptorGravity>.size,
                                                 options: [])!
    let gravityConstantData = MTLVertexDescriptorGravity()
    gravityConstantData.gravity = 9.81

    let gravityFunction = library.newFunction(name: "gravity",
                                             constantBuffers: [gravityConstantBuffer],
                                             constants: [gravityConstantData])

    return gravityFunction!
}
```
